export const source = ":::exam-question\nid: ar1-t-p020-q01\ntitle: الكتاب · ص 18 · PDF 20 · السؤال 1\nquestion: نذكر سرّ بكاء الشاعر كما فهمنا من المقطع الأول.\nreference: الكتاب · ص 18 · PDF 20 · السؤال 1\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنذكر سرّ بكاء الشاعر كما فهمنا من المقطع الأول.\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\nالحنين إلى أيام طفولته وقريته التي رحلت أيامها الجميلة.\nsolution:\nيقول الكتاب:\n\n> أنا أبكي على **أيام قريتنا التي رحلت** وأبتهل\n\nالرزمة التعليمية، ص 17 (PDF 19).\n\nصرّح الشاعر بسبب بكائه: الحنين إلى أيام القرية والطفولة التي مضت، لا البكاء على دعوة الصديق نفسها.\n:::\n\n:::exam-question\nid: ar1-t-p020-q02\ntitle: الكتاب · ص 18 · PDF 20 · السؤال 2\nquestion: لماذا انفعل الشاعر عندما قرأ رسالة صديقه؟\nreference: الكتاب · ص 18 · PDF 20 · السؤال 2\nanswer-label: إجابة نموذجية للتدريب\nbody:\nلماذا انفعل الشاعر عندما قرأ رسالة صديقه؟\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\nلأن صديقه عيّره بطول بقائه في القدس، وزيّن له الرحيل إلى الخارج.\nsolution:\nتبيّن الأسطر أن الصديق يعيّره بأنه قابع في القدس ثم يزيّن له الرحيل. انفعل الشاعر لأن الرسالة تمسّ اختياره الوطني وتحوّل البقاء إلى أمر يُلام عليه، بينما يعدّه هو جزءًا من هويته.\n:::\n\n:::exam-question\nid: ar1-t-p020-q03\ntitle: الكتاب · ص 18 · PDF 20 · السؤال 3\nquestion: بم عُيّر الشاعر في النصّ؟\nreference: الكتاب · ص 18 · PDF 20 · السؤال 3\nanswer-label: إجابة نموذجية للتدريب\nbody:\nبم عُيّر الشاعر في النصّ؟\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\nعُيّر بأنه قابع في القدس، وأن بقاءه وحبّه لن ينقذاه ولن يندمل جرحه.\nsolution:\nيقول الكتاب:\n\n> تعيّرني بأني **قابع في القدس**\n\nالرزمة التعليمية، ص 17 (PDF 19).\n\nيتبع ذلك زعم الصديق بأن الحب لن ينقذه وأن جرحه لن يندمل؛ فالتعيير موجّه إلى بقائه وتمسّكه بالقدس.\n:::\n\n:::exam-question\nid: ar1-t-p020-q04\ntitle: الكتاب · ص 18 · PDF 20 · السؤال 4\nquestion: ماذا طلب الصديق من الشاعر؟\nreference: الكتاب · ص 18 · PDF 20 · السؤال 4\nanswer-label: إجابة نموذجية للتدريب\nbody:\nماذا طلب الصديق من الشاعر؟\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\nأن يغادر وطنه ويذهب إليه في المهجر، ووعده بحياة أفضل هناك.\nsolution:\nيقول الكتاب:\n\n> تزيّن لي **الرحيل**\n\nالرزمة التعليمية، ص 18 (PDF 20).\n\nويؤكّد الإغراء قوله «وتغريني بأنّي إن أتيت إليك مثل البدر أكتمل»؛ فالمطلوب مغادرة الوطن والذهاب إلى الصديق في المهجر.\n:::\n\n:::exam-question\nid: ar1-t-p020-q05\ntitle: الكتاب · ص 18 · PDF 20 · السؤال 5-أ\nquestion: نعيّن الأسطر الشعرية التي تعبّر عن الفكرة الآتية: يصل الإنسان إلى ما يريده بالجدّ والصبر.\nreference: الكتاب · ص 18 · PDF 20 · السؤال 5-أ\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنعيّن الأسطر الشعرية التي تعبّر عن الفكرة الآتية: يصل الإنسان إلى ما يريده بالجدّ والصبر.\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\n«نسيت بأنني البطء الذي في بطئه يصل».\nsolution:\nيقول الكتاب:\n\n> نسيت بأنني البطء الذي **في بطئه يصل**\n\nالرزمة التعليمية، ص 17 (PDF 19).\n\nدلالة الصبر لا تأتي من البطء وحده؛ بل من اقترانه بالوصول، فيؤكّد المثابرة رغم طول الطريق.\n:::\n\n:::exam-question\nid: ar1-t-p020-q06\ntitle: الكتاب · ص 18 · PDF 20 · السؤال 5-ب\nquestion: نعيّن الأسطر الشعرية التي تعبّر عن الفكرة الآتية: معاناة الأسرى، وتحمّلهم أذى المحتل.\nreference: الكتاب · ص 18 · PDF 20 · السؤال 5-ب\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنعيّن الأسطر الشعرية التي تعبّر عن الفكرة الآتية: معاناة الأسرى، وتحمّلهم أذى المحتل.\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\n«مَنِ اعتُقلوا ومَن صُلِبوا فما تابوا / ولا عن عدلهم عدلوا / ومَن عُزلوا / فما ملّوا عذاب سجونهم أبدًا».\nsolution:\nيقول الكتاب:\n\n> من اعتقلوا ومن صلبوا فما تابوا\n> ولا عن عدلهم عدلوا\n> ومن عزلوا\n**فما ملّوا عذاب سجونهم أبدا**\n\nالرزمة التعليمية، ص 18 (PDF 20).\n\nالأفعال تذكر صور الأذى، ونفي التراجع والملل يبيّن تحمّل الأسرى وثباتهم.\n:::\n\n:::exam-question\nid: ar1-t-p020-q07\ntitle: الكتاب · ص 18 · PDF 20 · السؤال 5-ج\nquestion: نعيّن الأسطر الشعرية التي تعبّر عن الفكرة الآتية: الثبات في الوطن.\nreference: الكتاب · ص 18 · PDF 20 · السؤال 5-ج\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنعيّن الأسطر الشعرية التي تعبّر عن الفكرة الآتية: الثبات في الوطن.\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\n«أنا جذر يناغي عمق هذي الأرض / مذ كانت / ومنذ تكوّن الأزل / وكوّن لحمها لحمي».\nsolution:\nيقول الكتاب:\n\n> **أنا جذر** يناغي عمق هذي الأرض\n> مذ كانت\n> ومنذ تكوّن الأزل\n> وكوّن لحمها لحمي\n\nالرزمة التعليمية، ص 17 (PDF 19).\n\nالجذر ثابت ومتّصل بعمق الأرض، وتشابك لحمها بلحمه يبرز أن انتماءه إليها من أصل كيانه.\n:::\n\n:::exam-question\nid: ar1-t-p021-q01\ntitle: الكتاب · ص 19 · PDF 21 · السؤال 1\nquestion: أشار الشاعر إلى ذكرياته في قريته، نصف تلك القرية.\nreference: الكتاب · ص 19 · PDF 21 · السؤال 1\nanswer-label: إجابة نموذجية للتدريب\nbody:\nأشار الشاعر إلى ذكرياته في قريته، نصف تلك القرية.\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\nقرية ذات أزقّة مقوّسة العقود وسقوف بيضاء، وصباح مبلّل بالندى، وحجل وقطعان تعود عند المغيب، وزيتون أخضر في وادٍ يضمّه الجبل.\nsolution:\nنبني الوصف من تفاصيل المقطع الأول: **الأزقّة المقوّسة والسقوف البيضاء** ترسم البيوت، و**الصبح المبلّل بالندى والمطر والزيتون** ترسم الطبيعة، و**قطعان الرعاة والحجل** تحيي الحركة في القرية. جمع التفاصيل يحفظ صورة القرية كما تذكّرها الشاعر.\n:::\n\n:::exam-question\nid: ar1-t-p021-q02\ntitle: الكتاب · ص 19 · PDF 21 · السؤال 2-أ\nquestion: نبيّن دلالة العبارة: فتورق في شفاه الحقل أغنية وتزدهر.\nreference: الكتاب · ص 19 · PDF 21 · السؤال 2-أ\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنبيّن دلالة العبارة: فتورق في شفاه الحقل أغنية وتزدهر.\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\nتدلّ على تجدد الحياة في الحقول بعد المطر وما يبعثه من بهجة؛ جعل للأرض شفاهًا تغنّي وللأغنية أوراقًا تتفتح.\nsolution:\nتسبق العبارةَ عودةُ المطر إلى الحقول؛ فالإيراق والازدهار أثره في النبات. وجعل الأغنية تورق والحقل ذا شفاه ينقل تجدد الخصب إلى فرح وغناء، لذلك تدل الصورة على **البهجة وتجدد الحياة**.\n:::\n\n:::exam-question\nid: ar1-t-p021-q03\ntitle: الكتاب · ص 19 · PDF 21 · السؤال 2-ب\nquestion: نبيّن دلالة العبارة: أنا جذر يناغي عمق هذي الأرض.\nreference: الكتاب · ص 19 · PDF 21 · السؤال 2-ب\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنبيّن دلالة العبارة: أنا جذر يناغي عمق هذي الأرض.\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\nتدلّ على رسوخ انتمائه إلى أرضه واتصاله بها اتصال الجذر بالتربة.\nsolution:\nاختار الشاعر **الجذر** لا الغصن؛ فهو موضع التثبّت في الأرض والتغذّي منها. و«يناغي عمق» يجعل الاتصال حميمًا مستمرًا؛ فتدل العبارة على رسوخ الانتماء ورفض الاقتلاع من الوطن.\n:::\n\n:::exam-question\nid: ar1-t-p021-q04\ntitle: الكتاب · ص 19 · PDF 21 · السؤال 2-ج\nquestion: نبيّن دلالة العبارة: اختلفت بنا السبل.\nreference: الكتاب · ص 19 · PDF 21 · السؤال 2-ج\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنبيّن دلالة العبارة: اختلفت بنا السبل.\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\nاختلفت اختياراتهما ومواقفهما؛ آثر الشاعر البقاء في الوطن وآثر صديقه الرحيل.\nsolution:\nتأتي العبارة ردًّا على إغراء الرحيل: الصديق يدعو إلى الهجرة، والشاعر يعلن أن دمه من نبض الأرض. فاختلاف «السبل» كناية عن **اختلاف القناعات والاختيارات**، لا مجرد تباعد الأماكن.\n:::\n\n:::exam-question\nid: ar1-t-p021-q05\ntitle: الكتاب · ص 19 · PDF 21 · السؤال 3-أ\nquestion: نوضّح جمال التصوير فيما يأتي: أني إن أتيت إليك مثل البدر أكتمل.\nreference: الكتاب · ص 19 · PDF 21 · السؤال 3-أ\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنوضّح جمال التصوير فيما يأتي: أني إن أتيت إليك مثل البدر أكتمل.\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\nشبّه ما وعده به الصديق من اكتمال حاله في المهجر باكتمال القمر بدرًا، في سياق الإغراء بالرحيل.\nsolution:\nالمشبّه هو حال الشاعر كما يعده الصديق إن هاجر، والمشبّه به **البدر**، وأداة التشبيه **مثل**. وجه الشبه الاكتمال؛ فالوعود تزيّن المهجر كأنه سيكمل حياته، لكنه يرفضها.\n:::\n\n:::exam-question\nid: ar1-t-p021-q06\ntitle: الكتاب · ص 19 · PDF 21 · السؤال 3-ب\nquestion: نوضّح جمال التصوير فيما يأتي: سطورك لفّها الخجل.\nreference: الكتاب · ص 19 · PDF 21 · السؤال 3-ب\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنوضّح جمال التصوير فيما يأتي: سطورك لفّها الخجل.\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\nشبّه الخجل بغطاء يلفّ سطور الرسالة؛ للدلالة على ما فيها من دعوة مخجلة إلى ترك الوطن.\nsolution:\nالخجل إحساس معنوي لا يلفّ الورق حقيقة؛ نُقل إليه فعل الغطاء أو الرداء «لفّها». بهذه الاستعارة تتجسّد الرسالة في غطاء من الخجل، إيحاءً بأن الدعوة إلى ترك الوطن مخجلة في نظر الشاعر.\n:::\n\n:::exam-question\nid: ar1-t-p021-q07\ntitle: الكتاب · ص 19 · PDF 21 · السؤال 4\nquestion: نبيّن المغريات التي تدفع الإنسان إلى أن يهجر وطنه.\nreference: الكتاب · ص 19 · PDF 21 · السؤال 4\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنبيّن المغريات التي تدفع الإنسان إلى أن يهجر وطنه.\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\nمنها الوعد بالمال والعمل المريح والمكانة والأمن والعيش بعيدًا عن المعاناة.\nsolution:\nالقرينة في القصيدة هي وعد الصديق بأن يكتمل الشاعر إن أتى إليه. يمكن أن تشمل مغريات الهجرة **المال والعمل والمكانة والأمن**؛ والمطلوب بيان أمثلة محتملة مرتبطة بفكرة الإغراء، مع تمييزها من موقف الشاعر الذي يقدّم الانتماء.\n:::\n\n:::exam-question\nid: ar1-t-p021-q08\ntitle: الكتاب · ص 19 · PDF 21 · السؤال 5\nquestion: نوازن بين الشاعر وصديقه من حيث: التمسّك بالوطن، وحبّ الثروة والجاه.\nreference: الكتاب · ص 19 · PDF 21 · السؤال 5\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنوازن بين الشاعر وصديقه من حيث: التمسّك بالوطن، وحبّ الثروة والجاه.\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\nالشاعر ثابت في الوطن، يقدّم الانتماء على المال والجاه؛ والصديق اختار المهجر وزيّن للشاعر ما فيه من رخاء ومكانة.\nsolution:\nنقارن على المحورين المطلوبين: **الوطن** عند الشاعر اتصال بالدم والجذر، لذا يختار البقاء؛ أما الصديق فاختار المهجر ويدعوه إليه. وفي **الثروة والجاه** يرفض الشاعر أن تكون بديلًا للوطن، بينما يقدّم الصديق وعد الحياة الأكمل حُجّة للرحيل.\n:::\n\n:::exam-question\nid: ar1-t-p021-q09\ntitle: الكتاب · ص 19 · PDF 21 · السؤال 6\nquestion: صمود الشاعر كان بصبره وبشعره، ما السلاح الذي يدافع به الطلبة عن أوطانهم؟\nreference: الكتاب · ص 19 · PDF 21 · السؤال 6\nanswer-label: إجابة نموذجية للتدريب\nbody:\nصمود الشاعر كان بصبره وبشعره، ما السلاح الذي يدافع به الطلبة عن أوطانهم؟\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\nالعلم والدفاتر، مع الوعي بتاريخ الوطن والعمل لخدمته. ويمثّل النص صمود الطلبة بقوله «سلاحهم الحجارة والدفاتر».\nsolution:\nيقول الكتاب:\n\n> سلاحهم الحجارة و**الدفاتر**\n\nالرزمة التعليمية، ص 18 (PDF 20).\n\nإضافة الدفاتر إلى السلاح تربط صمود الطلبة بالعلم والتعلّم والوعي. لذلك يمكن أن يذكر الطالب العلم والعمل لخدمة الوطن، مع ربط الاستنتاج بلفظ الدفاتر في النصّ.\n:::\n\n:::exam-question\nid: ar1-t-p021-q10\ntitle: الكتاب · ص 19 · PDF 21 · السؤال 7\nquestion: وظّف الشاعر في قصيدته اللون والحركة والصوت، نصنّف كلّ عبارة وفق ما يناسبها في الجدول:\nreference: الكتاب · ص 19 · PDF 21 · السؤال 7\nanswer-label: إجابة نموذجية للتدريب\nbody:\nوظّف الشاعر في قصيدته اللون والحركة والصوت، نصنّف كلّ عبارة وفق ما يناسبها في الجدول:\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\n\n| العبارات | اللون | الحركة | الصوت |\n| --- | --- | --- | --- |\n| صبحها الخضل | | | |\n| وتورق في شفاه الحقل | | | |\n| نفض ريشه الحجل | | | |\n| إن ردّوا وإن سألوا | | | |\n| تسرق خضرة الزيتون | | | |\n| ومن بترابهم جُبلوا | | | |\n| أنا جذر يناغي عمق هذي الأرض | | | |\nfinal-answer:\n| العبارة | العنصر الأبرز |\n| --- | --- |\n| صبحها الخضل | اللون |\n| وتورق في شفاه الحقل | الحركة |\n| نفض ريشه الحجل | الحركة |\n| إن ردّوا وإن سألوا | الصوت |\n| تسرق خضرة الزيتون | اللون |\n| ومن بترابهم جُبلوا | الحركة |\n| أنا جذر يناغي عمق هذي الأرض | الصوت |\nsolution:\nنبحث عن العنصر الحسّي الأبرز، وقد تحتمل الصورة أكثر من عنصر:\n\n- **صبحها الخضل** يرسم مشهد الصباح الندي المرئي، فيغلب اللون.\n- **تورق في شفاه الحقل** و**نفّض ريشه الحجل** فيهما نموّ النبات وحركة الطائر، فتغلب الحركة.\n- **إن ردّوا وإن سألوا** كلام مسموع، فيغلب الصوت.\n- **خضرة الزيتون** تسمّي اللون مباشرة.\n- **بترابهم جُبلوا** يشير إلى فعل التكوين والمزج، فيُدرج في الحركة.\n- **يناغي** تواصل بصوت رقيق، فيُدرج في الصوت.\n\nهذا تصنيف للصورة الشعرية بحسب العنصر البارز، لا حصر لكل لفظ في حاسة واحدة.\n:::\n\n:::exam-question\nid: ar1-t-p021-q11\ntitle: الكتاب · ص 19 · PDF 21 · السؤال 1\nquestion: نفرّق في المعنى بين ما تحته خطّ في كلّ مما يأتي:\nreference: الكتاب · ص 19 · PDF 21 · السؤال 1\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنفرّق في المعنى بين ما تحته خطّ في كلّ مما يأتي:\n\n- أ. أزقّتها مقوّسة <u>العقود</u>.\n- ب. رزح شعبنا تحت الاحتلال <u>عقودًا</u> من الزمن.\n- ج. توثّق <u>عقود</u> الزواج في المحكمة الشرعية.\nfinal-answer:\nأ. الأقواس المعمارية فوق الأزقّة. ب. فترات كلّ واحدة منها عشر سنوات. ج. وثائق واتفاقات الزواج.\nsolution:\nنحدّد المعنى من المضاف إليه والسياق: **مقوّسة العقود** تصف بناء الأزقّة فالعقود أقواس معمارية؛ و**عقودًا من الزمن** وحدات زمنية كلّ منها عشر سنوات؛ و**عقود الزواج توثّق** اتفاقات ووثائق. تشابه الصورة اللفظية لا يلغي اختلاف الاستعمال.\n:::\n\n:::exam-question\nid: ar1-t-p022-q01\ntitle: الكتاب · ص 20 · PDF 22 · السؤال 2\nquestion: وظّف الشاعر في قصيدته أسلوب الحوار بينه وبين صديقه، ما أثر ذلك على جمال القصيدة؟\nreference: الكتاب · ص 20 · PDF 22 · السؤال 2\nanswer-label: إجابة نموذجية للتدريب\nbody:\nوظّف الشاعر في قصيدته أسلوب الحوار بينه وبين صديقه، ما أثر ذلك على جمال القصيدة؟\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\nأحيا الموقف، وكشف اختلاف الصديقين، وجعل ردّ الشاعر وتمسّكه بالوطن أقرب إلى المتلقّي.\nsolution:\nيتحاور موقفان: يزيّن الصديق الرحيل، ويردّ الشاعر بإعلان الانتماء. هذا التبادل يكشف الدوافع والاختلاف ويمنح القصيدة حركة وتشويقًا وحُجّة؛ فيرى القارئ ثبات الشاعر من ردّه على الإغراء، لا من وصف مجرّد.\n:::\n\n:::exam-question\nid: ar1-t-p022-q02\ntitle: الكتاب · ص 20 · PDF 22 · السؤال 3\nquestion: نهل الشاعر من قاموس التراث الشعبي، نعيّن المفردات التي وظّفها منه.\nreference: الكتاب · ص 20 · PDF 22 · السؤال 3\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنهل الشاعر من قاموس التراث الشعبي، نعيّن المفردات التي وظّفها منه.\n\n### نص الدرس: رسالة إلى صديق قديم\n\n(١)\n\nأنا أبكي على أيّام قريتنا التي رحلت وأبتهل  \nأزقّتها مقوّسة العقود وصبحها الخضل  \nومغربها الذي برجوع قطعان الرّعاة إليه يكتحل  \nوفوق سقوفها البيضاء نفّض ريشه الحجل  \nوكيف يجيئها المطر  \nفتورق في شفاه الحقل أغنية وتزدهر  \nفتجتمع العذارى والزّهور  \nالطّير والأبقار والأغنام  \nفي عرس المساء بها وتحتفل  \nأحنّ إلى طفولتنا فسحر روائها ثمل  \nتقادم عهدها  \nكأنّا ما رسمنا الرّيح  \nتسرق خضرة الزّيتون  \nفي الوادي الذي قد ضمّه الجبل\n\nوأحفظ في شراييني الأحاديث التي باحت  \nبها القبل  \nوأحمل في خلاياي الذين بحبّهم قتلوا  \nومن بترابهم ودمائهم جبلوا  \nمن اعتقلوا ومن صلبوا فما تابوا  \nولا عن عدلهم عدلوا  \nومن عزلوا  \nفما ملّوا عذاب سجونهم أبدًا  \nبل إنّ غرامهم ملل  \nومن وصلوا ضمير ذواتهم عشقًا  \nولم يصلوا  \nوأحفظ في شراييني الذين عيونهم أمل  \nسلاحهم الحجارة والدّفاتر  \nوالحبّ الذي في سرّهم حملوا  \nفلسطينيّة أحزانهم في الدّرس  \nإن ردّوا وإن سألوا\n\n(٢)\n\nوأنّك مثلما عوّدتني  \nقد عدت تؤذيني وأحتمل  \nتعيّرني بأنّي قابع في القدس  \nلا حبّي سينقذني ولا جرحي سيندمل  \nتقول بأنّني سأموت  \nفي بطء خرافي  \nوسوف أموت  \nلا وطن ولا مال ولا مثل  \nنسيت بأنّني البطء الذي في بطئه يصل  \nأنا جذر يناغي عمق هذي الأرض  \nمذ كانت  \nومنذ تكوّن الأزل  \nوكوّن لحمها لحمي  \nوتحت ظلال زيتون الجليل أهمّني الغزل\n\nسطورك في رسالتك الأثيرة  \nلفّها الخجل  \nتراودني الحروف ذليلة  \nوتذلّني الجمل  \nتزيّن لي الرّحيل  \nكأن لا يكفيك من رحلوا  \nوتغريني بأنّي إن أتيت إليك  \nمثل البدر أكتمل  \nفشكرًا يا صديق طفولتي  \nاختلفت بنا السّبل  \nأنا نبض التراب دمي  \nفكيف أخون نبض دمي وأرتحل؟\n\nالنص من الكتاب، ص 17–18\nfinal-answer:\nمنها الأزقّة مقوّسة العقود، والحجل، وقطعان الرعاة، والعذارى، وعرس المساء، والزيتون.\nsolution:\nمن ألفاظ التراث الشعبي **الأزقّة مقوّسة العقود، والحجل، وقطعان الرعاة، والعذارى، وعرس المساء، والزيتون**. يجمعها اتصالها بالعمران الريفي والعادات والبيئة الفلسطينية في ذاكرة القرية.\n:::\n\n:::exam-question\nid: ar1-t-p022-q03\ntitle: الكتاب · ص 20 · PDF 22 · السؤال 4-أ\nquestion: نعرب ما تحته خطّ: <u>أنا جذر</u> يناغي عمق هذي الأرض.\nreference: الكتاب · ص 20 · PDF 22 · السؤال 4-أ\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنعرب ما تحته خطّ: <u>أنا جذر</u> يناغي عمق هذي الأرض.\nfinal-answer:\nأنا: ضمير منفصل مبني في محل رفع مبتدأ. جذرٌ: خبر مرفوع بالضمة.\nsolution:\nالجملة تبدأ باسم ولا يسبقها ناسخ: **أنا** ضمير منفصل مبني في محل رفع مبتدأ. و**جذرٌ** يكمّل معنى المبتدأ ويخبر عنه، فهو خبر مرفوع بالضمة. ثم تأتي «يناغي» لتصف الجذر؛ فلا تجعل جذرًا فاعلًا للفعل اللاحق.\n:::\n\n:::exam-question\nid: ar1-t-p022-q04\ntitle: الكتاب · ص 20 · PDF 22 · السؤال 4-ب\nquestion: نعرب ما تحته خطّ: <u>سلاحهم الحجارة</u> والدفاتر.\nreference: الكتاب · ص 20 · PDF 22 · السؤال 4-ب\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنعرب ما تحته خطّ: <u>سلاحهم الحجارة</u> والدفاتر.\nfinal-answer:\nسلاحُهم: مبتدأ مرفوع بالضمة، وهو مضاف، و«هم» ضمير في محل جر مضاف إليه. الحجارةُ: خبر مرفوع بالضمة.\nsolution:\n**سلاحُهم** مسند إليه في أول الجملة، فهو مبتدأ مرفوع بالضمة؛ وهو مضاف و«هم» ضمير متصل في محل جر مضاف إليه. و**الحجارةُ** تخبر عن السلاح فتكون خبرًا مرفوعًا بالضمة، والدفاتر معطوفة عليها.\n:::\n\n:::exam-question\nid: ar1-t-p027-q09\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 3-1\nquestion: ما سرّ بكاء الشاعر كما فهمت من المقطع السابق؟\nreference: الكتاب · ص 25 · PDF 27 · السؤال 3-1\nanswer-label: إجابة نموذجية للتدريب\nbody:\nما سرّ بكاء الشاعر كما فهمت من المقطع السابق؟\n\n**نص السؤال 3**\n\nنقرأ الأسطر الشعرية الآتية من قصيدة (رسالة إلى صديق قديم)، ثم نجيب عن الأسئلة التي تليها:\n\n> أنا أبكي على أيام قريتنا التي رحلت وأبتهلُ  \n> أزقّتها مقوّسة العقود وصبحُها الخضِلُ  \n> ومغربُها الذي برجوع قطعان الرعاة إليه يكتحلُ  \n> وفوق سقوفها البيضاء نفّض ريشه الحجلُ  \n> وكيف يحيّيها المطرُ  \n> فتورق في شفاه الحقل أغنية وتزدهرُ\nfinal-answer:\nحنّ إلى قريته وأيام طفولته فيها بعد أن مضت.\nsolution:\nقرينة «أنا أبكي على أيام قريتنا التي رحلت» تربط البكاء بأيام ماضية فقدها الشاعر. ثم يستعيد مشاهد القرية وطفولته؛ فسبب البكاء **الحنين إلى القرية وأيام الطفولة بعد انقضائها**، وليس ألمًا جسديًا أو حزنًا بلا سبب محدّد.\n:::\n\n:::exam-question\nid: ar1-t-p027-q10\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 3-2\nquestion: نذكر مؤلّفًا نثريًّا من مؤلّفات الشاعر عبد اللطيف عقل.\nreference: الكتاب · ص 25 · PDF 27 · السؤال 3-2\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنذكر مؤلّفًا نثريًّا من مؤلّفات الشاعر عبد اللطيف عقل.\n\n**نص السؤال 3**\n\nنقرأ الأسطر الشعرية الآتية من قصيدة (رسالة إلى صديق قديم)، ثم نجيب عن الأسئلة التي تليها:\n\n> أنا أبكي على أيام قريتنا التي رحلت وأبتهلُ  \n> أزقّتها مقوّسة العقود وصبحُها الخضِلُ  \n> ومغربُها الذي برجوع قطعان الرعاة إليه يكتحلُ  \n> وفوق سقوفها البيضاء نفّض ريشه الحجلُ  \n> وكيف يحيّيها المطرُ  \n> فتورق في شفاه الحقل أغنية وتزدهرُ\nfinal-answer:\nمسرحية «البلاد طلبت أهلها».\nsolution:\nمن المؤلّفات النثرية لعبد اللطيف عقل مسرحية **«البلاد طلبت أهلها»**.\n:::\n\n:::exam-question\nid: ar1-t-p027-q11\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 3-3\nquestion: (أبتهل، أزقّتها)، ما مرادف الأولى؟ وما مفرد الثانية؟\nreference: الكتاب · ص 25 · PDF 27 · السؤال 3-3\nanswer-label: إجابة نموذجية للتدريب\nbody:\n(أبتهل، أزقّتها)، ما مرادف الأولى؟ وما مفرد الثانية؟\n\n**نص السؤال 3**\n\nنقرأ الأسطر الشعرية الآتية من قصيدة (رسالة إلى صديق قديم)، ثم نجيب عن الأسئلة التي تليها:\n\n> أنا أبكي على أيام قريتنا التي رحلت وأبتهلُ  \n> أزقّتها مقوّسة العقود وصبحُها الخضِلُ  \n> ومغربُها الذي برجوع قطعان الرعاة إليه يكتحلُ  \n> وفوق سقوفها البيضاء نفّض ريشه الحجلُ  \n> وكيف يحيّيها المطرُ  \n> فتورق في شفاه الحقل أغنية وتزدهرُ\nfinal-answer:\nأبتهل: أتضرّع وأدعو. مفرد أزقّتها: زقاق.\nsolution:\n**أبتهل: أتضرّع وأدعو. ومفرد أزقّتها: زقاق.**\n:::\n\n:::exam-question\nid: ar1-t-p027-q12\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 3-4\nquestion: ما العاطفة التي برزت في الأسطر الشعرية السابقة؟\nreference: الكتاب · ص 25 · PDF 27 · السؤال 3-4\nanswer-label: إجابة نموذجية للتدريب\nbody:\nما العاطفة التي برزت في الأسطر الشعرية السابقة؟\n\n**نص السؤال 3**\n\nنقرأ الأسطر الشعرية الآتية من قصيدة (رسالة إلى صديق قديم)، ثم نجيب عن الأسئلة التي تليها:\n\n> أنا أبكي على أيام قريتنا التي رحلت وأبتهلُ  \n> أزقّتها مقوّسة العقود وصبحُها الخضِلُ  \n> ومغربُها الذي برجوع قطعان الرعاة إليه يكتحلُ  \n> وفوق سقوفها البيضاء نفّض ريشه الحجلُ  \n> وكيف يحيّيها المطرُ  \n> فتورق في شفاه الحقل أغنية وتزدهرُ\nfinal-answer:\nالحنين إلى القرية وأيام الطفولة فيها، الممزوج بالحزن على انقضائها.\nsolution:\nيستعيد الشاعر القرية ومطرها وحقولها وعودة الرعاة، ويصرّح بالبكاء على أيام رحلت. اجتماع الاستعادة المحبّة مع الإحساس بالفقد يكشف **حنينًا إلى القرية والطفولة ممتزجًا بالحزن على انقضاء تلك الأيام**.\n:::\n\n:::exam-question\nid: ar1-t-p027-q13\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 3-5\nquestion: نذكر ملامح البساطة التي صوّرها الشاعر في قريته التي رحل عنها.\nreference: الكتاب · ص 25 · PDF 27 · السؤال 3-5\nanswer-label: إجابة نموذجية للتدريب\nbody:\nنذكر ملامح البساطة التي صوّرها الشاعر في قريته التي رحل عنها.\n\n**نص السؤال 3**\n\nنقرأ الأسطر الشعرية الآتية من قصيدة (رسالة إلى صديق قديم)، ثم نجيب عن الأسئلة التي تليها:\n\n> أنا أبكي على أيام قريتنا التي رحلت وأبتهلُ  \n> أزقّتها مقوّسة العقود وصبحُها الخضِلُ  \n> ومغربُها الذي برجوع قطعان الرعاة إليه يكتحلُ  \n> وفوق سقوفها البيضاء نفّض ريشه الحجلُ  \n> وكيف يحيّيها المطرُ  \n> فتورق في شفاه الحقل أغنية وتزدهرُ\nfinal-answer:\nالأزقّة المعقودة والسقوف البيضاء، وعودة قطعان الرعاة عند المغرب، والحجل فوق السقوف والحقول التي تحيا بالمطر.\nsolution:\nنستخرج الملامح من الصور المحسوسة في المقطع: **الأزقّة المعقودة، والسقوف البيضاء، وعودة قطعان الرعاة عند المغرب، والحجل فوق السقوف، والحقول التي يحييها المطر**. هذه مشاهد قرية زراعية هادئة، فتجسّد البساطة التي يطلبها السؤال.\n:::\n\n:::exam-question\nid: ar1-t-p027-q14\ntitle: الكتاب · ص 25 · PDF 27 · السؤال 3-6\nquestion: نكتب ثمانية أسطر شعرية أخرى من القصيدة.\nreference: الكتاب · ص 25 · PDF 27 · السؤال 3-6\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nنكتب ثمانية أسطر شعرية أخرى من القصيدة.\n\n**نص السؤال 3**\n\nنقرأ الأسطر الشعرية الآتية من قصيدة (رسالة إلى صديق قديم)، ثم نجيب عن الأسئلة التي تليها:\n\n> أنا أبكي على أيام قريتنا التي رحلت وأبتهلُ  \n> أزقّتها مقوّسة العقود وصبحُها الخضِلُ  \n> ومغربُها الذي برجوع قطعان الرعاة إليه يكتحلُ  \n> وفوق سقوفها البيضاء نفّض ريشه الحجلُ  \n> وكيف يحيّيها المطرُ  \n> فتورق في شفاه الحقل أغنية وتزدهرُ\nfinal-answer:\n> فتجتمع العذارى والزهور  \n> الطير والأبقار والأغنام  \n> في عرس المساء بها وتحتفل  \n> أحنّ إلى طفولتنا فسحر روائها ثمل  \n> تقادم عهدها  \n> كأنّا ما رسمنا الريح  \n> تسرق خضرة الزيتون  \n> في الوادي الذي قد ضمّه الجبل\nsolution:\nالمطلوب حفظ الأسطر وإثبات ترتيبها:\n\n> فتجتمع العذارى والزهور  \n> الطير والأبقار والأغنام  \n> في عرس المساء بها وتحتفل  \n> أحنّ إلى طفولتنا فسحر روائها ثمل  \n> تقادم عهدها  \n> كأنّا ما رسمنا الريح  \n> تسرق خضرة الزيتون  \n> في الوادي الذي قد ضمّه الجبل\n:::\n\n:::mcq\nid: ar1-e-p031-q01\ntitle: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 1 · 2019\nkicker: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 1 · 2019\nreference: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 1 · 2019\nquestion: ما دلالة (السُّبل) في قول عبد اللطيف عقل: اختلفت بنا السبل؟\n- [x] option-1 | الآراء.\n- [ ] option-2 | أماكن الإقامة.\n- [ ] option-3 | المواعيد.\n- [ ] option-4 | الظروف.\nexplanation:\nيقول الشاعر لصديقه ذلك بعد أن دعاه إلى الرحيل، ثم يعلن تمسّكه بالأرض. ليست «السبل» طرقًا جغرافية هنا، بل **الآراء والقناعات والاختيارات**؛ اختار الصديق الهجرة واختار الشاعر البقاء.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-e-p031-q02\ntitle: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 2 · 2019\nkicker: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 2 · 2019\nreference: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 2 · 2019\nquestion: ما السطر الشعريّ الذي يعبّر عن الثبات في قصيدة عبد اللطيف عقل؟\n- [ ] option-1 | نسيت بأنّني البطء الذي في بطئه يصل.\n- [ ] option-2 | فما ملّوا عذاب سجونهم أبدًا.\n- [x] option-3 | أنا جذر يناغي عمق هذي الأرض.\n- [ ] option-4 | وأحفظ في شراييني الذين عيونهم أمل.\nexplanation:\nيقول الكتاب:\n\n> **أنا جذر** يناغي عمق هذي الأرض\n\nالرزمة التعليمية، ص 17 (PDF 19).\n\nالجذر ثابت في التربة ومتصل بعمقها؛ فاختياره صورة لنفسه يدلّ على الثبات والانتماء إلى الوطن.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-e-p031-q03\ntitle: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 3 · 2020\nkicker: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 3 · 2020\nreference: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 3 · 2020\nquestion: أيّ من الأعمال الأدبيّة الآتية من دواوين الشاعر (عبد اللطيف عقل)؟\n- [x] option-1 | شواطئ القمر.\n- [ ] option-2 | البلاد طلبت أهلها.\n- [ ] option-3 | شهد العزلة.\n- [ ] option-4 | أنّات حائرة.\nexplanation:\nيقول الكتاب:\n\n> صدر له كثير من المجموعات الشعرية، منها: (**شواطئ القمر**)، و(أغاني القمة والقاع)\n\nالرزمة التعليمية، ص 17 (PDF 19).\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-e-p031-q04\ntitle: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 4 · 2020\nkicker: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 4 · 2020\nreference: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 4 · 2020\nquestion: بم وصف (عبد اللطيف عقل) نفسه بقوله: «نسيت بأنّني البطء الذي في بطئه يصل»؟\n- [ ] option-1 | الحكمة والذكاء.\n- [x] option-2 | العزيمة والإصرار.\n- [ ] option-3 | الكسل والخمول.\n- [ ] option-4 | ثقل الحركة.\nexplanation:\nلا ينتهي السطر عند كلمة البطء؛ بل يقيّدها بقوله **«في بطئه يصل»**. الوصول مع طول الطريق يعبّر عن المثابرة والصبر، ولذلك يدلّ الوصف على **العزيمة والإصرار**، وليس الكسل.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-e-p031-q05\ntitle: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 5 · 2020\nkicker: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 5 · 2020\nreference: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 5 · 2020\nquestion: أيّ من العبارات الآتية وظّف الشاعر فيها عنصر الحركة؟\n- [ ] option-1 | إن ردّوا وإن سألوا.\n- [ ] option-2 | أنا جذر يناغي.\n- [ ] option-3 | صبحها الخضل.\n- [x] option-4 | نفّض ريشه الحجل.\nexplanation:\nفي **«نفّض ريشه الحجل»** فعل حركي يصف اهتزاز ريش الطائر ونفضه؛ فيستحضر القارئ مشهدًا متحرّكًا. أمّا «إن ردّوا وإن سألوا» فيبرز فيه الصوت، و«صبحها الخضل» يركّز على المشهد المرئي.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-e-p031-q06\ntitle: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 6 · 2021\nkicker: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 6 · 2021\nreference: مجموعة الامتحانات · ص 30 · PDF 31 · السؤال 6 · 2021\nquestion: ماذا أضافت صورة «سقوفها البيضاء» إلى وصف الشاعر لقريته؟\n- [ ] option-1 | النقاء والطهارة.\n- [x] option-2 | جمال القرية وبساطة بيوتها.\n- [ ] option-3 | العلوّ والأنفة.\n- [ ] option-4 | الثبات والبقاء.\nexplanation:\nالسقوف البيضاء جزء من مشهد الأزقّة والرعاة والحجل في القرية. اجتماع هذه التفاصيل يصنع صورة مألوفة جميلة لحياة ريفية بسيطة؛ لذلك الأثر هو **جمال القرية وبساطة بيوتها**، وليس دليلًا على الترف.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-e-p032-q01\ntitle: مجموعة الامتحانات · ص 31 · PDF 32 · السؤال 7 · 2021\nkicker: مجموعة الامتحانات · ص 31 · PDF 32 · السؤال 7 · 2021\nreference: مجموعة الامتحانات · ص 31 · PDF 32 · السؤال 7 · 2021\nquestion: ما معنى (عقد) في عبارة: (رزح شعبنا تحت الاحتلال عقودًا من الزمن)؟\n- [ ] option-1 | السقف المقوّس.\n- [ ] option-2 | الاتّفاق الموقّع بين طرفين.\n- [ ] option-3 | ما تتزيّن به المرأة.\n- [x] option-4 | عشر سنوات.\nexplanation:\nالقرينة **«من الزمن»** تجعل «عقد» وحدة زمنية، ومقدارها **عشر سنوات**. يختلف هذا الاستعمال عن العقد المعماري أو عقد الزواج، وإن تشابهت الحروف.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::mcq\nid: ar1-e-p032-q02\ntitle: مجموعة الامتحانات · ص 31 · PDF 32 · السؤال 8 · 2021\nkicker: مجموعة الامتحانات · ص 31 · PDF 32 · السؤال 8 · 2021\nreference: مجموعة الامتحانات · ص 31 · PDF 32 · السؤال 8 · 2021\nquestion: ماذا أفادت الزيادة في الفعل في عبارة (نفّض ريشه الحجل)؟\n- [ ] option-1 | التعدية.\n- [x] option-2 | المبالغة.\n- [ ] option-3 | الصيرورة.\n- [ ] option-4 | المطاوعة.\nexplanation:\n«نفّض» على وزن **فعّل** بتضعيف الفاء من الجذر ن ف ض. في وصف الطائر الذي يحرّك ريشه تُفيد الزيادة تقوية فعل النفض وتكراره؛ أي **المبالغة**.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\n:::\n\n:::exam-question\nid: ar1-e-p032-q03\ntitle: مجموعة الامتحانات · ص 31 · PDF 32 · السؤال 1 · 2019، الدورة الثانية، شهر 8\nquestion: اقرأ الأسطر الشعريّة الآتية من قصيدة (رسالة إلى صديق قديم)، ثمّ أجب عن الأسئلة التي تليها:\nreference: مجموعة الامتحانات · ص 31 · PDF 32 · السؤال 1 · 2019، الدورة الثانية، شهر 8\nanswer-label: إجابة المفتاح المرفق\nbody:\nاقرأ الأسطر الشعريّة الآتية من قصيدة (رسالة إلى صديق قديم)، ثمّ أجب عن الأسئلة التي تليها:\n\n> أنا أبكي على أيّام قريتنا التي رحلت وأبتهلُ  \n> أزقّتها مقوّسة العقود وصبحها الخضلُ  \n> ومغربها الذي برجوع قطعان الرعاة إليه يكتحلُ  \n> وفوق سقوفها البيضاء نفّض ريشه الحجلُ  \n> وكيف يحيّيها المطرُ  \n> فتورق في شفاه الحقل أغنية وتزدهرُ\n\n- أ. ما سرّ بكاء الشاعر؟\n- ب. ما معنى كلمة (الخضل)؟\n- ج. ما دلالة: (فتورق في شفاه الحقل أغنية وتزدهر)؟\n- د. ما الغرض البلاغيّ للاستفهام في عبارة «فكيف أخون نبض دمي وأرتحل»؟\n- هـ. وظّف الشاعر ألفاظًا من قاموس التراث الشعبيّ، أعطِ مثالًا واحدًا يوضّح ذلك.\nfinal-answer:\n- أ. لأنّه تذكّر قريته، والأيّام الجميلة التي قضاها، ويتمنّى عودة هذه الأيام.\n- ب. الخضل: المبلّل بالنّدى.\n- ج. للدلالة على حالة السّرور والابتهاج.\n- د. أسلوب استفهام، غرضه التعجّب والاستنكار.\n- هـ. قريتنا، أزقّتها، مقوّسة العقود، قطعان الرعاة، الحجل.\nsolution:\nأ. يصرّح السطر الأول بالبكاء على «أيّام قريتنا التي رحلت»، فيتعلّق الحزن بفقد الأيام الجميلة والحنين إليها.\n\nب. يشرح هامش القصيدة «الخضل» بأنه **المبلّل بالندى**.\n\nج. الإيناع بعد المطر وظهور الأغنية ينقلان تجدّد الحياة والسرور؛ أُعطيت الحقول شفاهًا، والأغنية فعل النبات «تورق».\n\nد. يربط الشاعر الرحيل بخيانة دمه؛ فالسؤال «فكيف أخون؟» لا يطلب جوابًا، بل يستنكر إمكان الهجرة ويتعجّب منه.\n\nهـ. تكفي مفردة تراثية مثل **الحجل** أو **قطعان الرعاة**، لأنها تستحضر عناصر القرية وحياتها الشعبية، مع ربطها بالنصّ.\n:::\n\n:::exam-question\nid: ar1-e-p033-q01\ntitle: مجموعة الامتحانات · ص 32 · PDF 33 · السؤال 2 · 2020، الدورة الأولى، شهر 6\nquestion: اقرأ الأسطر الشعريّة الآتية من قصيدة (رسالة إلى صديق قديم)، ثمّ أجب عن الأسئلة التي تليها:\nreference: مجموعة الامتحانات · ص 32 · PDF 33 · السؤال 2 · 2020، الدورة الأولى، شهر 6\nanswer-label: إجابة المفتاح المرفق\nbody:\nاقرأ الأسطر الشعريّة الآتية من قصيدة (رسالة إلى صديق قديم)، ثمّ أجب عن الأسئلة التي تليها:\n\n> وتغريني بأنّي إن أتيت إليك  \n> مثل البدر أكتملُ  \n> فشكرًا يا صديق طفولتي  \n> اختلفت بنا السبلُ  \n> أنا نبض التراب دمي  \n> فكيف أخون نبض دمي وأرتحلُ؟\n\n- أ. كشفت الأسطر الشعريّة عن مدى وطنيّة الشاعر، وضّح ذلك.\n- ب. ما دلالة قول الشاعر: «اختلفت بنا السبل»؟\n- ج. وردت كلمة (نبض) في النصّ مرّتين، اضبط آخرها في كلّ منهما.\n- د. ما الغرض البلاغيّ للاستفهام في عبارة «فكيف أخون نبض دمي وأرتحل»؟\n- هـ. اكتب ستّة أسطر شعريّة من قصيدة (رسالة إلى صديق قديم) للشاعر (عبد اللطيف عقل).\nfinal-answer:\n- أ. تمسّك الشاعر بأرضه ووطنه، ورفضه كلّ المغريات التي تحدّث عنها صديقه.\n- ب. دلالة على اختلاف الشاعر وصديقه وعدم اتّفاقهما في التفكير، وفي القناعات.\n- ج. نبضُ. نبضَ.\n- د. أسلوب استفهام، غرضه التعجّب والاستنكار.\n- هـ. من نصّ الكتاب:\n\n> أنا أبكي على أيّام قريتنا التي رحلت وأبتهلُ  \n> أزقّتها مقوّسة العقود وصبحها الخضلُ  \n> ومغربها الذي برجوع قطعان الرعاة إليه يكتحلُ  \n> وفوق سقوفها البيضاء نفّض ريشه الحجلُ  \n> وكيف يحيّيها المطرُ  \n> فتورق في شفاه الحقل أغنية وتزدهرُ\nsolution:\nأ. يردّ الشاعر على وعد الاكتمال في المهجر بتشبيه علاقته بالأرض بعلاقة الدم بالنبض؛ فحبّ الوطن جزء من كيانه لا مصلحة مادية عابرة.\n\nب. «اختلفت بنا السبل» اختلاف في القناعات: دعوة الصديق إلى الرحيل تقابلها إرادة الشاعر في البقاء.\n\nج. في «أنا نبضُ التراب» نبض خبر مرفوع، أما «أخون نبضَ دمي» فهي مفعول به منصوب؛ لذلك الضبط **نبضُ، نبضَ**.\n\nد. الاستفهام استنكاري تعجّبي، لأن الشاعر ينفي أن يرضى بخيانة انتمائه.\n\nهـ. الحفظ نقلٌ من القصيدة لا إنشاء جديد؛ تُختار ستّة أسطر متتابعة من نصّ الكتاب، مثل المقطع الذي يبدأ «أنا أبكي على أيام قريتنا».\n:::\n\n:::exam-question\nid: ar1-e-p033-q02\ntitle: مجموعة الامتحانات · ص 32 · PDF 33 · السؤال 3 · 2020، الدورة الثالثة، شهر 12\nquestion: اقرأ الأسطر الشعريّة الآتية للشاعر (عبد اللطيف عقل)، ثمّ أجب عن الأسئلة التي تليها:\nreference: مجموعة الامتحانات · ص 32 · PDF 33 · السؤال 3 · 2020، الدورة الثالثة، شهر 12\nanswer-label: إجابة المفتاح المرفق\nbody:\nاقرأ الأسطر الشعريّة الآتية للشاعر (عبد اللطيف عقل)، ثمّ أجب عن الأسئلة التي تليها:\n\n> مَن اعتقلوا ومَن صلبوا فما تابوا  \n> ولا عن عدلهم عدلوا  \n> ومَن عُزلوا  \n> فما ملّوا عذاب سجونهم أبدًا  \n> بل إنّ غرامهم مللُ\n\n- أ. ما الفكرة التي عبّر عنها الشاعر في هذه الأسطر؟\n- ب. ما المقصود بعبارة «ولا عن عدلهم عدلوا»؟\n- ج. استخرج من النصّ حرف عطف يفيد الإضراب.\nfinal-answer:\n- أ. فخر الشاعر بالأسرى والمعتقلين وتضحياتهم وصمودهم.\n- ب. دلالة على الإصرار والعزيمة وعدم التنازل عن الحقّ.\n- ج. بل.\nsolution:\nأ. تعداد الاعتقال والصلب والعزل، ثم نفي التراجع والملل، يظهر **الفخر بصمود الأسرى وتضحياتهم**.\n\nب. «عدلهم» الأولى بمعنى حقّهم، و«عدلوا» الثانية بمعنى حادوا أو رجعوا؛ ونفي العدول يؤكّد عدم التنازل عن الحقّ.\n\nج. حرف العطف **بل** ينقل الكلام من نفي ملل السجن إلى تقرير أن غرامهم بالوطن هو ما يلازمهم؛ ولهذا يفيد الإضراب.\n:::\n\n:::exam-question\nid: ar1-e-p034-q01\ntitle: مجموعة الامتحانات · ص 33 · PDF 34 · السؤال 4 · 2021، الدورة الأولى، الأدبي، شهر 6\nquestion: اقرأ الأسطر الشعريّة الآتية من (رسالة إلى صديق قديم)، ثمّ أجب عن الأسئلة التي تليها:\nreference: مجموعة الامتحانات · ص 33 · PDF 34 · السؤال 4 · 2021، الدورة الأولى، الأدبي، شهر 6\nanswer-label: إجابة المفتاح المرفق\nbody:\nاقرأ الأسطر الشعريّة الآتية من (رسالة إلى صديق قديم)، ثمّ أجب عن الأسئلة التي تليها:\n\n> سطورك في رسالتك الأثيرة، لفّها الخجلُ  \n> تراودني الحروف ذليلةً، وتذلّني الجملُ  \n> تزيّن لي الرحيل، كأن لا يكفيك مَن رحلوا  \n> وتغريني بأنّي إن أتيت إليك، مثل البدر أكتملُ  \n> فشكرًا يا صديق طفولتي، اختلفت بنا السبلُ  \n> أنا نبض التراب دمي، فكيف أخون نبض دمي وأرتحلُ؟\n\n- أ. وصف الشاعر سطور الرسالة بعدّة صفات، اكتب اثنتين منها.\n- ب. بم يعد الصديق الشاعر إن رحل عن الوطن؟\n- ج. وضّح الصورة الفنيّة في عبارة (نبض التراب).\n- د. فسّر معنى جملة (اختلفت بنا السبل).\n- هـ. اكتب ستّة أسطر شعريّة من قصيدة (أنا وليلى).\nfinal-answer:\n- أ. هذه الرسالة أحاطها الخجل والذلّ والمهانة، وصديقه يزيّن له الرحيل فيرفض هجرة الوطن.\n- ب. وعده إن قبل الرحيل أنّه سيكون مثل البدر جمالًا واكتمالًا، لكنّ الشاعر قابله بعزيمة وإصرار فيرفض دعوة صديقه.\n- ج. شبّه التراب بقلب ينبض كما شبّه نبض التراب بدمه.\n- د. دلالة على اختلاف الرأي والقناعات والطرق بينهما، فكلّ منهما يسير في طريق مختلف.\n- هـ. من نصّ الكتاب:\n\n> ماتت بمحراب عينيك ابتهالاتي / واستسلمت لرياح اليأس راياتي  \n> جفّت على بابك الموصود أزمنتي / ليلى، وما أثمرت شيئًا نداءاتي  \n> ممزّق أنا، لا جاه ولا ترف / يغريك فيّ، فخلّيني لآهاتي  \n> لو تعصرين سنين العمر أكملها / لسال منها نزيفٌ من جراحاتي  \n> لو كنت ذا ترفٍ ما كنت رافضةً / حبّي، ولكنّ عسر الحال مأساتي  \n> عانيت، عانيت لا حزني أبوح به / ولست تدرين شيئًا عن معاناتي\nsolution:\nأ. تُستخرج صفتا الخجل والذل من «لفّها الخجل» و«الحروف ذليلة»؛ فالشاعر يرفض رسالة تزيّن له ترك الوطن.\n\nب. «مثل البدر أكتمل» هو الوعد بالاكتمال وحياة أفضل في المهجر، وهو إغراء يرده الشاعر.\n\nج. في «نبض التراب» أصبح التراب كائنًا حيًا ذا قلب؛ ثم اتّصل ذلك بدم الشاعر، لتجسيد الاندماج بالأرض.\n\nد. اختلاف السبل اختلاف في الموقف من الهجرة، لا مجرّد اختلاف في المسكن.\n\nهـ. الفرع يطلب الحفظ من **أنا وليلى** رغم أن المقتطف من رسالة إلى صديق قديم؛ لذلك تُنقل ستة أسطر من القصيدة المطلوبة، ولا تُستبدل بأسطر المقتطف.\n:::\n\n:::exam-question\nid: ar1-e-p034-q02\ntitle: مجموعة الامتحانات · ص 33 · PDF 34 · السؤال 5 · 2021، الدورة الأولى، العلمي، شهر 6\nquestion: اقرأ الأسطر الشعريّة الآتية من (رسالة إلى صديق قديم)، ثمّ أجب عن الأسئلة التي تليها:\nreference: مجموعة الامتحانات · ص 33 · PDF 34 · السؤال 5 · 2021، الدورة الأولى، العلمي، شهر 6\nanswer-label: إجابة المفتاح المرفق\nbody:\nاقرأ الأسطر الشعريّة الآتية من (رسالة إلى صديق قديم)، ثمّ أجب عن الأسئلة التي تليها:\n\n> سطورك في رسالتك الأثيرة  \n> لفّها الخجلُ  \n> تراودني الحروف ذليلةً  \n> وتذلّني الجملُ  \n> تزيّن لي الرحيل  \n> كأن لا يكفيك مَن رحلوا\n\n- أ. ما مضمون الرسالة التي وجّهها الصديق للشاعر؟\n- ب. ما العاطفة التي سيطرت على الشاعر في هذه الأسطر؟\n- ج. وظّف الشاعر أسلوب الحوار، ما أثر ذلك على جمال القصيدة؟\n- د. وضّح جمال التصوير في قول الشاعر: «سطورك لفّها الخجل».\n- هـ. اكتب ستّة أسطر شعريّة من قصيدة (رسالة إلى صديق قديم).\nfinal-answer:\n- أ. يدعوه للرحيل ومغادرة الوطن، ويغريه بالهجرة.\n- ب. عاطفة الحزن والألم.\n- ج. الكشف عن الدوافع، ومحاولة إقناع الطرف الآخر بالرأي الصائب. وفّر عنصر التشويق والإقناع، وسهّل على المتعلّم فهم النصّ.\n- د. شبّه الخجل برداء يلفّ الرسالة، وشبّه السطور بكائن حيّ يخجل.\n- هـ. من نصّ الكتاب:\n\n> أنا أبكي على أيّام قريتنا التي رحلت وأبتهلُ  \n> أزقّتها مقوّسة العقود وصبحها الخضلُ  \n> ومغربها الذي برجوع قطعان الرعاة إليه يكتحلُ  \n> وفوق سقوفها البيضاء نفّض ريشه الحجلُ  \n> وكيف يحيّيها المطرُ  \n> فتورق في شفاه الحقل أغنية وتزدهرُ\nsolution:\nأ. تكشف «تزيّن لي الرحيل» مباشرة دعوة الرسالة إلى الهجرة.\n\nب. وصف السطور بالخجل والحروف بالذل يدلّ على **الحزن والألم** من موقف صديق طفولته.\n\nج. الحوار يقابل حُجّة الإغراء بحُجّة الانتماء، فيكشف دوافع الشخصيتين ويشرك القارئ في الموقف بدل الاكتفاء بتقرير الفكرة.\n\nد. شُبّه الخجل برداء يلفّ الرسالة، والسطور بكائن يخجل؛ فصارت الفكرة المعنوية صورة محسوسة.\n\nهـ. يطلب الحفظ ستّة أسطر من القصيدة نفسها؛ يُراعى نصّ الكتاب وترتيب الأسطر، مثل مقطع الحنين إلى القرية الوارد في الإجابة.\n:::\n\n:::exam-question\nid: ar1-e-p035-q01\ntitle: مجموعة الامتحانات · ص 34 · PDF 35 · السؤال 6 · 2022، الدورة الأولى، شهر 6\nquestion: اقرأ الأسطر الشعريّة الآتية من (رسالة إلى صديق قديم)، ثمّ أجب عن الأسئلة التي تليها:\nreference: مجموعة الامتحانات · ص 34 · PDF 35 · السؤال 6 · 2022، الدورة الأولى، شهر 6\nanswer-label: إجابة المفتاح المرفق\nbody:\nاقرأ الأسطر الشعريّة الآتية من (رسالة إلى صديق قديم)، ثمّ أجب عن الأسئلة التي تليها:\n\n> أحنّ إلى طفولتنا فسحر رؤاها ثملُ  \n> تقادم عهدها  \n> كأنّا ما رسمنا الريح  \n> تسرق خضرة الزيتون  \n> في الوادي الذي قد ضمّه <u>الجبلُ</u>\n\n- أ. وردت في النصّ الكلمتان (ثمل، الجبل) المعنى الصرفيّ للأولى، وإعراب الثانية.\n- ب. وضّح جمال التصوير في قول الشاعر: «تسرق خضرة الزيتون في الوادي».\n- ج. وازن بين الشاعر وصديقه من حيث حبّ الثروة والجاه.\n- هـ. اكتب بيتين تحفظهما من قصيدة (أنا وليلى).\nfinal-answer:\n- أ. ثمل: صفة مشبّهة، الجبل: فاعل مؤخّر مرفوع وعلامة رفعه الضمّة.\n- ب. شبّه الريح بالشخص السارق الذي يسرق خضرة وجمال الزيتون.\n- ج. الشاعر متمسّك بالوطن ويرفض كلّ المغريات. صديقه ليس لديه الارتباط الوثيق بالوطن ويسعى وراء الجاه والثروة.\n- هـ. من نصّ الكتاب:\n\n> ماتت بمحراب عينيك ابتهالاتي / واستسلمت لرياح اليأس راياتي  \n> جفّت على بابك الموصود أزمنتي / ليلى، وما أثمرت شيئًا نداءاتي\nsolution:\nأ. «ثمل» وصف يدلّ على صفة، وهو **صفة مشبّهة**. وفي «قد ضمّه الجبلُ» الهاء مفعول به متقدّم يعود على الوادي، والجبل هو الذي قام بالضمّ؛ فهو **فاعل مؤخّر مرفوع**.\n\nب. إسناد «تسرق» إلى الريح يصوّرها بإنسان سارق، وخضرة الزيتون شيئًا يُسرق؛ فيبرز تعلّق الذاكرة بجمال القرية.\n\nج. يُظهر الشاعر تقديم الانتماء إلى الوطن على مغريات المال والمكانة، بينما يزيّن الصديق حياة المهجر؛ فتقارن الإجابة بين الموقفين وفق النصّ.\n\nهـ. المطلوب بيتان من **أنا وليلى**؛ يُختاران من النصّ المحفوظ مع الحفاظ على شطري كل بيت، لا من قصيدة رسالة إلى صديق قديم.\n:::";

